  "gate": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/braids/v0.1/gate.schema.json",
    "title": "gate",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.gate/0.1"
      },
      "gate_id": {
        "$ref": "primitives.schema.json#/$defs/name"
      },
      "version": {
        "$ref": "primitives.schema.json#/$defs/semver"
      },
      "fingerprint": {
        "$ref": "primitives.schema.json#/$defs/fingerprint_jcs1"
      },
      "protocol": {
        "const": "gate_io/0.1"
      },
      "scripts": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "runtime": {
              "enum": [
                "python",
                "js"
              ]
            },
            "entry": {
              "$ref": "primitives.schema.json#/$defs/file_ref"
            },
            "script_fingerprint": {
              "$ref": "primitives.schema.json#/$defs/fingerprint_raw"
            }
          },
          "required": [
            "runtime",
            "entry",
            "script_fingerprint"
          ]
        },
        "maxItems": 2,
        "minItems": 1,
        "allOf": [
          {
            "not": {
              "contains": {
                "properties": {
                  "runtime": {
                    "const": "python"
                  }
                },
                "required": [
                  "runtime"
                ]
              },
              "minContains": 2
            }
          },
          {
            "not": {
              "contains": {
                "properties": {
                  "runtime": {
                    "const": "js"
                  }
                },
                "required": [
                  "runtime"
                ]
              },
              "minContains": 2
            }
          }
        ]
      },
      "applies_to": {
        "type": "array",
        "items": {
          "$ref": "primitives.schema.json#/$defs/versioned_ref"
        },
        "maxItems": 20
      },
      "config": {
        "type": [
          "object",
          "null"
        ]
      },
      "network": {
        "anyOf": [
          {
            "const": "none"
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "allow": {
                "type": "array",
                "items": {
                  "type": "string",
                  "maxLength": 253,
                  "pattern": "^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+(?![\\s\\S])"
                },
                "maxItems": 20,
                "minItems": 1
              }
            },
            "required": [
              "allow"
            ]
          }
        ]
      },
      "reads_rows": {
        "type": "boolean"
      },
      "timeout_s": {
        "type": "integer",
        "minimum": 1,
        "maximum": 900
      },
      "vectors": {
        "$ref": "primitives.schema.json#/$defs/file_ref"
      }
    },
    "required": [
      "schema",
      "gate_id",
      "version",
      "fingerprint",
      "protocol",
      "scripts",
      "applies_to",
      "config",
      "network",
      "reads_rows",
      "timeout_s",
      "vectors"
    ],
    "description": "gate.json (\xA73.8). Its fingerprint covers the scripts; both runtimes must match the vectors exactly (TPL-07)."
  },
