  "decision_card_v0_1": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/decision_card_v0_1.schema.json",
    "title": "decision_card_v0_1",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.decision_card/0.1"
      },
      "question": {
        "type": "string",
        "maxLength": 300
      },
      "context": {
        "type": "string",
        "maxLength": 1200
      },
      "options": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "option_id": {
              "type": "string",
              "maxLength": 64,
              "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
            },
            "label": {
              "type": "string",
              "maxLength": 80
            },
            "summary": {
              "type": "string",
              "maxLength": 600
            },
            "what_changes": {
              "type": "string",
              "maxLength": 600
            }
          },
          "required": [
            "option_id",
            "label",
            "summary",
            "what_changes"
          ]
        },
        "maxItems": 8,
        "minItems": 2
      },
      "recommendation": {
        "anyOf": [
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "option_id": {
                "type": "string",
                "maxLength": 64,
                "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
              },
              "reason": {
                "type": "string",
                "maxLength": 600
              }
            },
            "required": [
              "option_id",
              "reason"
            ]
          },
          {
            "type": "null"
          }
        ]
      },
      "evidence_refs": {
        "type": "array",
        "items": {
          "type": "string",
          "maxLength": 80,
          "pattern": "^[A-Za-z0-9_.:-]+(?![\\s\\S])"
        },
        "maxItems": 20
      }
    },
    "required": [
      "schema",
      "question",
      "context",
      "options",
      "recommendation",
      "evidence_refs"
    ],
    "description": "Presentation format for every decide step: the agent fills it, Fairlead code renders it."
  },
  "decision_card_v0_2": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/decision_card_v0_2.schema.json",
    "title": "decision_card_v0_2",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.decision_card/0.2"
      },
      "run_id": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/id_run"
      },
      "step_id": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/step_id"
      },
      "question": {
        "type": "string",
        "maxLength": 300
      },
      "context": {
        "type": "string",
        "maxLength": 1200
      },
      "options": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "option_id": {
              "type": "string",
              "maxLength": 64,
              "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
            },
            "label": {
              "type": "string",
              "maxLength": 80
            },
            "summary": {
              "type": "string",
              "maxLength": 600
            },
            "route": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "action": {
                  "enum": [
                    "continue",
                    "loop",
                    "skip",
                    "stop"
                  ]
                },
                "to": {
                  "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/step_id"
                }
              },
              "required": [
                "action"
              ],
              "allOf": [
                {
                  "if": {
                    "properties": {
                      "action": {
                        "enum": [
                          "loop",
                          "skip"
                        ]
                      }
                    },
                    "required": [
                      "action"
                    ]
                  },
                  "then": {
                    "required": [
                      "to"
                    ]
                  }
                },
                {
                  "if": {
                    "properties": {
                      "action": {
                        "enum": [
                          "continue",
                          "stop"
                        ]
                      }
                    },
                    "required": [
                      "action"
                    ]
                  },
                  "then": {
                    "not": {
                      "anyOf": [
                        {
                          "required": [
                            "to"
                          ]
                        }
                      ]
                    }
                  }
                }
              ]
            },
            "what_changes": {
              "type": "string",
              "maxLength": 300
            },
            "takes_direction": {
              "type": "boolean"
            }
          },
          "required": [
            "option_id",
            "label",
            "summary",
            "route",
            "what_changes",
            "takes_direction"
          ],
          "allOf": [
            {
              "if": {
                "properties": {
                  "takes_direction": {
                    "const": true
                  }
                },
                "required": [
                  "takes_direction"
                ]
              },
              "then": {
                "properties": {
                  "route": {
                    "properties": {
                      "action": {
                        "enum": [
                          "loop",
                          "continue"
                        ]
                      }
                    },
                    "required": [
                      "action"
                    ]
                  }
                }
              }
            }
          ]
        },
        "maxItems": 6,
        "minItems": 2
      },
      "notes": {
        "type": "array",
        "items": {
          "type": "string",
          "maxLength": 300
        },
        "maxItems": 6
      },
      "answer_by": {
        "enum": [
          "question_tool",
          "option_id"
        ]
      },
      "evidence_refs": {
        "type": "array",
        "items": {
          "type": "string",
          "maxLength": 80,
          "pattern": "^[A-Za-z0-9_.:-]+(?![\\s\\S])"
        },
        "maxItems": 20
      }
    },
    "required": [
      "schema",
      "run_id",
      "step_id",
      "question",
      "context",
      "options",
      "notes",
      "answer_by",
      "evidence_refs"
    ],
    "description": "Every decide step. Options are neutral: no recommendation field, and labels, routes and what_changes are copied from the template and the server; a recommendation, if any, is in the question. answer_by is question_tool with at most four options, else option_id (format_gate)."
  },
