  "frame_choices_v0_1": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/frame_choices_v0_1.schema.json",
    "title": "frame_choices_v0_1",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.frame_choices/0.1"
      },
      "decision_id": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/id_dec"
      },
      "items": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "key": {
              "type": "string",
              "maxLength": 64,
              "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
            },
            "choice": {
              "anyOf": [
                {
                  "type": "string",
                  "maxLength": 64,
                  "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
                },
                {
                  "type": "null"
                }
              ]
            },
            "own": {
              "anyOf": [
                {
                  "type": "string",
                  "maxLength": 600,
                  "minLength": 1
                },
                {
                  "type": "null"
                }
              ]
            },
            "drop": {
              "type": "boolean"
            },
            "value": {
              "anyOf": [
                {
                  "type": "string",
                  "maxLength": 600
                },
                {
                  "type": "null"
                }
              ]
            },
            "review_item": {
              "anyOf": [
                {
                  "type": "string",
                  "maxLength": 8,
                  "pattern": "^R[0-9]{1,3}(?![\\s\\S])"
                },
                {
                  "type": "null"
                }
              ]
            },
            "unverified": {
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "option_id": {
                    "type": "string",
                    "maxLength": 64,
                    "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
                  },
                  "source_ids": {
                    "type": "array",
                    "items": {
                      "type": "string",
                      "maxLength": 80,
                      "pattern": "^[A-Za-z0-9_.:-]+(?![\\s\\S])"
                    },
                    "maxItems": 10,
                    "minItems": 1
                  },
                  "answer": {
                    "enum": [
                      "keep",
                      "remove"
                    ]
                  }
                },
                "required": [
                  "option_id",
                  "source_ids",
                  "answer"
                ]
              },
              "maxItems": 3
            },
            "supplied": {
              "type": "boolean"
            },
            "sent_to_review": {
              "type": "boolean"
            }
          },
          "required": [
            "key",
            "choice",
            "own",
            "drop",
            "value",
            "review_item"
          ],
          "allOf": [
            {
              "if": {
                "properties": {
                  "drop": {
                    "const": true
                  }
                },
                "required": [
                  "drop"
                ]
              },
              "then": {
                "properties": {
                  "choice": {
                    "type": "null"
                  },
                  "own": {
                    "type": "null"
                  },
                  "value": {
                    "type": "null"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "sent_to_review": {
                    "const": true
                  }
                },
                "required": [
                  "sent_to_review"
                ]
              },
              "then": {
                "required": [
                  "supplied"
                ],
                "properties": {
                  "drop": {
                    "const": false
                  },
                  "supplied": {
                    "const": true
                  },
                  "choice": {
                    "type": "null"
                  },
                  "own": {
                    "type": "null"
                  },
                  "value": {
                    "type": "null"
                  }
                }
              }
            },
            {
              "if": {
                "allOf": [
                  {
                    "properties": {
                      "drop": {
                        "const": false
                      }
                    },
                    "required": [
                      "drop"
                    ]
                  },
                  {
                    "not": {
                      "properties": {
                        "sent_to_review": {
                          "const": true
                        }
                      },
                      "required": [
                        "sent_to_review"
                      ]
                    }
                  }
                ]
              },
              "then": {
                "properties": {
                  "value": {
                    "type": "string",
                    "maxLength": 600,
                    "minLength": 1
                  }
                },
                "oneOf": [
                  {
                    "properties": {
                      "choice": {
                        "type": "string",
                        "maxLength": 64,
                        "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
                      },
                      "own": {
                        "type": "null"
                      }
                    }
                  },
                  {
                    "properties": {
                      "choice": {
                        "type": "null"
                      },
                      "own": {
                        "type": "string",
                        "maxLength": 600,
                        "minLength": 1
                      }
                    }
                  }
                ]
              }
            }
          ]
        },
        "maxItems": 40
      }
    },
    "required": [
      "schema",
      "decision_id",
      "items"
    ],
    "description": "Written by the server from the person's answers on a choice card: per item, an offered option, the person's own value, or drop (exactly one), and the value it resolves to."
  },
