  "json_change_set_v0_1": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/json_change_set_v0_1.schema.json",
    "title": "json_change_set_v0_1",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.json_change_set/0.1"
      },
      "of": {
        "type": "string",
        "maxLength": 64,
        "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
      },
      "from_fingerprint": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/fingerprint"
      },
      "to_fingerprint": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/fingerprint"
      },
      "ops": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "op": {
              "enum": [
                "add",
                "remove",
                "replace"
              ]
            },
            "path": {
              "type": "string",
              "maxLength": 300,
              "pattern": "^(/[^/]*)+(?![\\s\\S])"
            },
            "from_value": {},
            "to_value": {},
            "cut": {
              "type": "boolean"
            }
          },
          "required": [
            "op",
            "path"
          ],
          "allOf": [
            {
              "if": {
                "properties": {
                  "op": {
                    "const": "add"
                  }
                },
                "required": [
                  "op"
                ]
              },
              "then": {
                "required": [
                  "to_value"
                ],
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "from_value"
                      ]
                    }
                  ]
                }
              }
            },
            {
              "if": {
                "properties": {
                  "op": {
                    "const": "remove"
                  }
                },
                "required": [
                  "op"
                ]
              },
              "then": {
                "required": [
                  "from_value"
                ],
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "to_value"
                      ]
                    }
                  ]
                }
              }
            },
            {
              "if": {
                "properties": {
                  "op": {
                    "const": "replace"
                  }
                },
                "required": [
                  "op"
                ]
              },
              "then": {
                "required": [
                  "from_value",
                  "to_value"
                ]
              }
            }
          ]
        },
        "maxItems": 200
      },
      "truncated": {
        "type": "boolean"
      }
    },
    "required": [
      "schema",
      "of",
      "from_fingerprint",
      "to_fingerprint",
      "ops",
      "truncated"
    ],
    "description": "Computed by Fairlead code for a step that reads <port>_changes (dev ask 12): the operations that turn the port's previous version into its current one, at most 200 (truncated when cut); strings over 600 characters are cut (cut: true). Round 1: ops empty, from_fingerprint equals to_fingerprint."
  },
